import re

def cmp_semver(a, b):
    def parse_version(v):
        # Split off build metadata
        if '+' in v:
            v = v.split('+', 1)[0]
        # Split off pre-release
        if '-' in v:
            parts = v.split('-', 1)
            version_part = parts[0]
            prerelease = parts[1]
        else:
            version_part = v
            prerelease = None
        # Parse major.minor.patch
        match = re.match(r'^(\d+)\.(\d+)\.(\d+)$', version_part)
        if not match:
            raise ValueError(f"Invalid version string: {v}")
        major, minor, patch = int(match.group(1)), int(match.group(2)), int(match.group(3))
        return (major, minor, patch, prerelease)

    def compare_prerelease(pre_a, pre_b):
        # None means no prerelease, which has higher precedence than any prerelease
        if pre_a is None and pre_b is None:
            return 0
        if pre_a is None:
            return 1  # a has no prerelease, so a > b
        if pre_b is None:
            return -1  # b has no prerelease, so a < b
        # Both have prerelease
        ids_a = pre_a.split('.')
        ids_b = pre_b.split('.')
        for i in range(min(len(ids_a), len(ids_b))):
            id_a = ids_a[i]
            id_b = ids_b[i]
            # Check if numeric
            is_num_a = id_a.isdigit()
            is_num_b = id_b.isdigit()
            if is_num_a and is_num_b:
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            elif is_num_a and not is_num_b:
                # Numeric identifiers always have lower precedence than alphanumeric
                return -1
            elif not is_num_a and is_num_b:
                return 1
            else:
                # Both alphanumeric, compare lexically
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1
        # All compared identifiers are equal, longer list has higher precedence
        if len(ids_a) < len(ids_b):
            return -1
        elif len(ids_a) > len(ids_b):
            return 1
        else:
            return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare major, minor, patch
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Compare prerelease
    return compare_prerelease(pre_a, pre_b)
