def parse_range(header, size):
    """
    Parse an RFC 7233 Range header for bytes.

    Args:
        header: The Range header value (e.g., "bytes=0-499")
        size: The total size of the resource in bytes

    Returns:
        A list of (start, end) inclusive byte offsets, or None if unsatisfiable/malformed.
    """
    if not header or not isinstance(header, str):
        return None

    header = header.strip()

    # Must start with "bytes="
    if not header.lower().startswith("bytes="):
        return None

    range_spec = header[6:].strip()

    if not range_spec:
        return None

    # Split by comma
    parts = [p.strip() for p in range_spec.split(",")]

    if not parts:
        return None

    ranges = []

    for part in parts:
        if not part:
            return None

        if "-" not in part:
            return None

        # Split into start and end
        dash_index = part.index("-")
        start_str = part[:dash_index].strip()
        end_str = part[dash_index+1:].strip()

        # Handle suffix range: bytes=-500
        if start_str == "":
            if end_str == "":
                return None
            try:
                suffix_length = int(end_str)
            except ValueError:
                return None
            if suffix_length <= 0:
                return None
            # Last suffix_length bytes
            start = max(0, size - suffix_length)
            end = size - 1
            if start > end:
                # Suffix length larger than resource yields whole resource
                start = 0
                end = size - 1
            ranges.append((start, end))
        else:
            # Regular range: bytes=start-end or bytes=start-
            try:
                start = int(start_str)
            except ValueError:
                return None

            if end_str == "":
                # bytes=500- means from 500 to end
                end = size - 1
            else:
                try:
                    end = int(end_str)
                except ValueError:
                    return None

            # Validate start
            if start < 0:
                return None

            # If start is at or past size, this range is unsatisfiable
            if start >= size:
                continue

            # Clamp end to size - 1
            if end >= size:
                end = size - 1

            # If end < start after clamping, unsatisfiable
            if end < start:
                continue

            ranges.append((start, end))

    if not ranges:
        return None

    return ranges
