def unified_diff(a, b, context=3):
    """
    Generate unified diff between two lists of lines.

    Args:
        a: First list of lines (without trailing newlines)
        b: Second list of lines (without trailing newlines)
        context: Number of context lines to include around changes

    Returns:
        List of unified diff output lines (without trailing newlines)
    """
    if a == b:
        return []

    # Compute LCS using dynamic programming
    n = len(a)
    m = len(b)

    # Build LCS table
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Backtrack to find the diff operations
    # We'll create a list of operations: ('equal', a_idx, b_idx), ('delete', a_idx), ('insert', b_idx)
    ops = []
    i, j = n, m
    while i > 0 or j > 0:
        if i > 0 and j > 0 and a[i - 1] == b[j - 1]:
            ops.append(('equal', i - 1, j - 1))
            i -= 1
            j -= 1
        elif j > 0 and (i == 0 or dp[i][j - 1] >= dp[i - 1][j]):
            ops.append(('insert', None, j - 1))
            j -= 1
        else:
            ops.append(('delete', i - 1, None))
            i -= 1

    ops.reverse()

    # Group operations into hunks
    # First, identify change regions (sequences of non-equal ops)
    # Then expand each change region by context lines and merge overlapping hunks

    # Find indices of changes in the ops list
    change_indices = []
    for idx, op in enumerate(ops):
        if op[0] != 'equal':
            change_indices.append(idx)

    if not change_indices:
        return []

    # Group consecutive changes into change groups
    change_groups = []
    current_group = [change_indices[0]]
    for k in range(1, len(change_indices)):
        if change_indices[k] == change_indices[k - 1] + 1:
            current_group.append(change_indices[k])
        else:
            change_groups.append(current_group)
            current_group = [change_indices[k]]
    change_groups.append(current_group)

    # For each change group, determine the hunk boundaries
    # A hunk includes context lines before and after the change group
    hunks = []
    for group in change_groups:
        start_op = group[0]
        end_op = group[-1]

        # Find the range of ops to include: context before start_op and context after end_op
        # We need to find how many equal ops are before start_op and after end_op

        # Count equal ops before start_op
        context_before = 0
        for k in range(start_op - 1, -1, -1):
            if ops[k][0] == 'equal':
                context_before += 1
                if context_before >= context:
                    break
            else:
                break

        # Count equal ops after end_op
        context_after = 0
        for k in range(end_op + 1, len(ops)):
            if ops[k][0] == 'equal':
                context_after += 1
                if context_after >= context:
                    break
            else:
                break

