class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.components = n
        self.history = []  # list of (a, b, size_a_before, size_b_before, components_before)

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)
        if root_a == root_b:
            return False
        # Union by size: attach smaller tree to larger tree
        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a
        # Now size[root_a] >= size[root_b]
        # Save state before merging
        self.history.append((root_a, root_b, self.size[root_a], self.size[root_b], self.components))
        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]
        self.components -= 1
        return True

    def snapshot(self):
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            root_a, root_b, size_a_before, size_b_before, components_before = self.history.pop()
            self.parent[root_b] = root_b
            self.size[root_a] = size_a_before
            self.size[root_b] = size_b_before
            self.components = components_before

    def components(self):
        return self.components
