def to_base(n, alphabet):
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet must contain distinct characters")

    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet must not be empty")

    if n == 0:
        return alphabet[0]

    negative = n < 0
    n = abs(n)

    digits = []
    while n > 0:
        remainder = n % base
        digits.append(alphabet[remainder])
        n //= base

    if negative:
        digits.append('-')

    return ''.join(reversed(digits))


def from_base(s, alphabet):
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet must contain distinct characters")

    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet must not be empty")

    if not s:
        raise ValueError("Input string must not be empty")

    negative = False
    if s[0] == '-':
        if len(s) == 1:
            raise ValueError("Invalid input: '-' alone is not a valid number")
        negative = True
        s = s[1:]

    if not s:
        raise ValueError("Input string must not be empty after sign")

    # Check all characters are in alphabet
    for char in s:
        if char not in alphabet:
            raise ValueError(f"Character '{char}' not in alphabet")

    # Convert from base
    result = 0
    for char in s:
        digit_value = alphabet.index(char)
        result = result * base + digit_value

    if negative:
        result = -result

    return result
