import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    # Dijkstra with heap
    # dist[node] = (cost, num_edges, path)
    # We want to minimize cost, then num_edges, then lexicographic path

    # Initialize distances
    INF = float('inf')
    dist = {src: (0, 0, [src])}
    heap = [(0, 0, src, [src])]  # (cost, num_edges, node, path)

    visited = set()

    while heap:
        cost, num_edges, node, path = heapq.heappop(heap)

        if node in visited:
            continue
        visited.add(node)

        if node == dst:
            return (cost, path)

        for neighbour, weight in graph.get(node, []):
            if neighbour in visited:
                continue
            new_cost = cost + weight
            new_num_edges = num_edges + 1
            new_path = path + [neighbour]

            # Check if this is a better path to neighbour
            if neighbour not in dist:
                dist[neighbour] = (new_cost, new_num_edges, new_path)
                heapq.heappush(heap, (new_cost, new_num_edges, neighbour, new_path))
            else:
                old_cost, old_num_edges, old_path = dist[neighbour]
                # Compare: first by cost, then by num_edges, then by lexicographic path
                if (new_cost, new_num_edges, new_path) < (old_cost, old_num_edges, old_path):
                    dist[neighbour] = (new_cost, new_num_edges, new_path)
                    heapq.heappush(heap, (new_cost, new_num_edges, neighbour, new_path))

    # dst unreachable
    return (None, [])
