function deepEqual(a, b) {
  // SameValueZero: NaN equals NaN, +0 equals -0
  if (a === b) return true;
  if (typeof a === 'number' && typeof b === 'number') {
    if (Number.isNaN(a) && Number.isNaN(b)) return true;
    if (a === 0 && b === 0) return true; // +0 and -0 are equal under SameValueZero
    return false;
  }

  // Different types are never equal
  if (typeof a !== typeof b) return false;

  // Handle null
  if (a === null || b === null) return false;

  // Handle Date
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  // Handle RegExp
  if (a instanceof RegExp && b instanceof RegExp) {
    return a.source === b.source && a.flags === b.flags;
  }

  // Handle Map
  if (a instanceof Map && b instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [key, value] of a) {
      if (!b.has(key)) return false;
      if (!deepEqual(value, b.get(key))) return false;
    }
    return true;
  }

  // Handle Set
  if (a instanceof Set && b instanceof Set) {
    if (a.size !== b.size) return false;
    // For Sets, we need to check if every element in a has a matching element in b
    // Since Sets don't have keys, we need to find a match for each element
    const bArray = Array.from(b);
    const matched = new Array(bArray.length).fill(false);
    for (const item of a) {
      let found = false;
      for (let i = 0; i < bArray.length; i++) {
        if (!matched[i] && deepEqual(item, bArray[i])) {
          matched[i] = true;
          found = true;
          break;
        }
      }
      if (!found) return false;
    }
    return true;
  }

  // Handle Arrays
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  // Handle plain objects (and other objects with enumerable own properties)
  if (typeof a === 'object' && typeof b === 'object') {
    // Check for cycles using a WeakMap to track visited pairs
    const visited = new WeakMap();

    function compare(objA, objB, seen) {
      // If we've already compared this pair, assume equal to avoid infinite recursion
      if (seen.has(objA)) {
        return seen.get(objA) === objB;
      }
      seen.set(objA, objB);

      // Get own enumerable keys
      const keysA = Object.keys(objA);
      const keysB = Object.keys(objB);

      if (keysA.length !== keysB.length) return false;

      for (const key of keysA) {
        if (!Object.prototype.hasOwnProperty.call(objB, key)) return false;
        if (!compare(objA[key], objB[key], seen)) return false;
      }

      return true;
    }

    return compare(a, b, new WeakMap());
  }

  return false;
}

