function pLimit(n) {
  let activeCount = 0;
  const queue = [];

  function next() {
    if (activeCount >= n || queue.length === 0) {
      return;
    }
    activeCount++;
    const { fn, resolve, reject } = queue.shift();
    fn().then(
      (value) => {
        activeCount--;
        resolve(value);
        next();
      },
      (err) => {
        activeCount--;
        reject(err);
        next();
      }
    );
  }

  return function (fn) {
    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      next();
    });
  };
}

module.exports = pLimit;
