const sqlTag = (strings, ...values) => {
  let text = '';
  const resultValues = [];
  let placeholderCount = 0;

  for (let i = 0; i < strings.length; i++) {
    text += strings[i];
    if (i < values.length) {
      const val = values[i];
      if (val && typeof val === 'object' && 'text' in val && 'values' in val && Array.isArray(val.values)) {
        // It's a result of sqlTag: inline it
        const subText = val.text;
        const subValues = val.values;
        // Renumber placeholders in subText
        // Find all $N in subText and replace with $(N + placeholderCount)
        const renumberedText = subText.replace(/\$(\d+)/g, (match, num) => {
          return '$' + (parseInt(num, 10) + placeholderCount);
        });
        text += renumberedText;
        resultValues.push(...subValues);
        placeholderCount += subValues.length;
      } else if (Array.isArray(val)) {
        // Array: parenthesised comma-separated list of placeholders
        const placeholders = val.map(() => {
          placeholderCount++;
          return '$' + placeholderCount;
        });
        text += '(' + placeholders.join(', ') + ')';
        resultValues.push(...val);
      } else {
        // Single value: positional placeholder
        placeholderCount++;
        text += '$' + placeholderCount;
        resultValues.push(val);
      }
    }
  }

  return { text, values: resultValues };
