function memoize(fn, keyFn) {
  const weakMap = new WeakMap();
  const map = new Map();
  let calls = 0;

  function memoized(...args) {
    let key;
    let useWeakMap = false;

    if (keyFn) {
      key = keyFn(...args);
    } else {
      if (args.length === 1 && typeof args[0] === 'object' && args[0] !== null) {
        key = args[0];
        useWeakMap = true;
      } else {
        key = args.length === 1 ? args[0] : args;
      }
    }

    let cache;
    if (useWeakMap) {
      cache = weakMap;
    } else {
      cache = map;
    }

    if (cache.has(key)) {
      return cache.get(key);
    }

    calls++;
    const result = fn(...args);
    cache.set(key, result);
    return result;
  }

  memoized.cache = {
    get calls() {
      return calls;
    },
    clear() {
      weakMap.clear();
      map.clear();
      calls = 0;
    }
  };

  return memoized;
}

module.exports = memoize;
