function parseQuery(qs) {
  if (!qs) return {};
  if (qs.startsWith('?')) qs = qs.slice(1);
  if (!qs) return {};

  const result = {};
  const pairs = qs.split('&');

  for (const pair of pairs) {
    if (!pair) continue;
    const eqIndex = pair.indexOf('=');
    let key, value;
    if (eqIndex === -1) {
      key = decodeURIComponent(pair.replace(/\+/g, ' '));
      value = '';
    } else {
      key = decodeURIComponent(pair.slice(0, eqIndex).replace(/\+/g, ' '));
      value = decodeURIComponent(pair.slice(eqIndex + 1).replace(/\+/g, ' '));
    }

    // Parse bracket notation
    const parts = [];
    let current = '';
    let inBracket = false;
    let depth = 0;
    for (let i = 0; i < key.length; i++) {
      const ch = key[i];
      if (ch === '[') {
        if (depth === 0) {
          parts.push(current);
          current = '';
        } else {
          current += ch;
        }
        depth++;
        inBracket = true;
      } else if (ch === ']') {
        depth--;
        if (depth === 0) {
          parts.push(current);
          current = '';
        } else {
          current += ch;
        }
        inBracket = false;
      } else {
        current += ch;
      }
    }
    if (current) parts.push(current);

    // parts[0] is the top-level key, subsequent parts are nested keys
    if (parts.length === 0) continue;

    const topKey = parts[0];
    const nestedKeys = parts.slice(1);

    // Helper to set value in nested structure
    function setValue(obj, keys, val) {
      if (keys.length === 0) {
        // Direct assignment
        if (Array.isArray(obj)) {
          // This shouldn't happen for top-level, but handle it
          obj.push(val);
        } else {
          obj[topKey] = val;
        }
        return;
      }

      let currentObj = obj;
      for (let i = 0; i < keys.length - 1; i++) {
        const k = keys[i];
        if (currentObj[k] === undefined) {
          // Determine if next key is numeric to decide array vs object
          const nextKey = keys[i + 1];
          if (/^\d+$/.test(nextKey)) {
            currentObj[k] = [];
          } else {
            currentObj[k] = {};
          }
        }
        currentObj = currentObj[k];
      }

      const lastKey = keys[keys.length - 1];
      if (lastKey === '') {
        // Empty bracket means append to array
        if (!Array.isArray(currentObj)) {
          // Convert to array if it's not already
          if (currentObj === undefined || currentObj === null) {
            currentObj = [];
          } else {
            // Wrap existing value in array
            const existing = currentObj;
            currentObj = [existing];
          }
        }
        currentObj.push(val);
      } else {
        if (Array.isArray(currentObj)) {
          // If currentObj is an array and lastKey is numeric, set by index
          if (/^\d+$/.test(lastKey)) {
            currentObj[parseInt(lastKey, 10)] = val;
          } else {
            // Convert to object
            const arr = currentObj;
            currentObj = {};
            for (let i = 0; i < arr.length; i++) {
              if (arr[i] !== undefined) {
                currentObj[i] = arr[i];
              }
            }
            currentObj[lastKey] = val;
          }
        } else {
          if (currentObj[lastKey] === undefined) {
            currentObj[lastKey] = val;
          } else {
            // Existing value, convert to array
            if (Array.isArray(currentObj[lastKey])) {
              currentObj[lastKey].push(val);
            } else {
              currentObj[lastKey] = [currentObj[lastKey], val];
            }
          }
        }
      }
    }

    if (nestedKeys.length === 0) {
      // Simple key
      if (result[topKey] === undefined) {
        result[topKey] = value;
      } else {
        if (Array.isArray(result[topKey])) {
          result[topKey].push(value);
        } else {
          result[topKey] = [result[topKey], value];
        }
      }
    } else {
      // Nested keys
      if (result[topKey] === undefined) {
        // Determine initial structure based on first nested key
        const firstNested = nestedKeys[0];
        if (firstNested === '') {
          result[topKey] = [];
        } else if (/^\d+$/.test(firstNested)) {
          result[topKey] = [];
        } else {
          result[topKey] = {};
        }
      }
      setValue(result, nestedKeys, value);
    }
  }

  return result;
}

function buildQuery(obj) {
  if (!obj || typeof obj !== 'object') return '';

  const pairs = [];

  function encodeValue(val) {
    return encodeURIComponent(String(val)).replace(/%20/g, '+');
  }

  function encodeKey(key) {
    return encodeURIComponent(String(key)).replace(/%20/g, '+');
  }

  function flatten(obj, prefix, isTopLevel) {
    if (obj === null || obj === undefined) return;

    if (Array.isArray(obj)) {
      for (let i = 0; i < obj.length; i++) {
        const item = obj[i];
        if (item === null || item === undefined) continue;
        if (typeof item === 'object') {
          flatten(item, `${prefix}[${i}]`, false);
        } else {
          pairs.push(`${encodeKey(prefix)}[${i}]=${encodeValue(item)}`);
        }
      }
    } else if (typeof obj === 'object') {
      const keys = Object.keys(obj).sort();
      for (const key of keys) {
        const val = obj[key];
        if (val === null || val === undefined) continue;
        const newPrefix = isTopLevel ? key : `${prefix}[${key}]`;
        if (typeof val === 'object') {
          flatten(val, newPrefix, false);
        } else {
          pairs.push(`${encodeKey(newPrefix)}=${encodeValue(val)}`);
        }
      }
    } else {
      // Should not reach here for top-level call
      pairs.push(`${encodeKey(prefix)}=${encodeValue(obj)}`);
    }
  }

  const keys = Object.keys(obj).sort();
  for (const key of keys) {
    const val = obj[key];
    if (val === null || val === undefined) continue;
    if (typeof val === 'object') {
      flatten(val, key, true);
    } else {
      pairs.push(`${encodeKey(key)}=${encodeValue(val)}`);
    }
  }

  return pairs.join('&');
}

module.exports = { parseQuery, buildQuery };
