    if (color[name] === BLACK) return false;
    color[name] = GRAY;
    const deps = tasks[name].deps || [];
    for (const dep of deps) {
      if (hasCycle(dep)) return true;
    }
    color[name] = BLACK;
    return false;
  }

  for (const name of names) {
    if (color[name] === WHITE) {
      if (hasCycle(name)) {
        return Promise.reject(new Error('cycle'));
      }
    }
  }

  // Build reverse dependency map: for each task, which tasks depend on it
  const dependents = {};
  for (const name of names) {
    dependents[name] = [];
  }
  for (const name of names) {
    const deps = tasks[name].deps || [];
    for (const dep of deps) {
      dependents[dep].push(name);
    }
  }

  // In-degree count for each task
  const inDegree = {};
  for (const name of names) {
    inDegree[name] = (tasks[name].deps || []).length;
  }

  const results = {};
  const completed = new Set();
  const failed = new Set();
  let firstError = null;
  let pendingCount = names.length;
  let resolvedCount = 0;

  return new Promise((resolve, reject) => {
    const queue = [];

    // Initialize queue with tasks that have no dependencies
    for (const name of names) {
      if (inDegree[name] === 0) {
        queue.push(name);
      }
    }

    function checkDone() {
      if (resolvedCount === names.length) {
        if (firstError) {
          reject(firstError);
        } else {
          resolve(results);
        }
      }
    }

    function processTask(name) {
      const task = tasks[name];
      const deps = task.deps || [];
      const depValues = {};
      for (const dep of deps) {
        depValues[dep] = results[dep];
      }

      const promise = Promise.resolve().then(() => task.run(depValues));

      promise.then((value) => {
        results[name] = value;
        completed.add(name);
        resolvedCount++;

        // Decrement in-degree of dependents
        for (const dependent of dependents[name]) {
          inDegree[dependent]--;
          if (inDegree[dependent] === 0) {
            queue.push(dependent);
          }
        }

        // Process next tasks in queue
        processQueue();
        checkDone();
      }).catch((err) => {
        failed.add(name);
        resolvedCount++;
        if (!firstError) {
          firstError = err;
        }

        // Mark all transitive dependents as failed (they won't run)
        const toMark = [name];
        const visited = new Set();
        while (toMark.length > 0) {
          const current = toMark.pop();
          if (visited.has(current)) continue;
          visited.add(current);
          for (const dependent of dependents[current]) {
            if (!visited.has(dependent)) {
              toMark.push(dependent);
            }
          }
        }
        for (const dep of visited) {
          if (!completed.has(dep) && !failed.has(dep)) {
            failed.add(dep);
            resolvedCount++;
          }
        }

        // Process next tasks in queue
        processQueue();
        checkDone();
      });
    }

    function processQueue() {
      while (queue.length > 0) {
        const name = queue.shift();
        if (failed.has(name)) {
          // This task depends on a failed task, mark as failed
          failed.add(name);
          resolvedCount++;
          // Propagate failure to dependents
          const toMark = [name];
          const visited = new Set();
          while (toMark.length > 0) {
            const current = toMark.pop();
            if (visited.has(current)) continue;
            visited.add(current);
            for (const dependent of dependents[current]) {
              if (!visited.has(dependent)) {
                toMark.push(dependent);
              }
            }
          }
          for (const dep of visited) {
            if (!completed.has(dep) && !failed.has(dep)) {
              failed.add(dep);
              resolvedCount++;
            }
          }
          checkDone();
          continue;
        }
        processTask(name);
      }
    }

    processQueue();
    checkDone();
  });
}

