export class Bus<E extends Record<string, unknown>> {
  private handlers: Map<keyof E, Set<(payload: any) => void>> = new Map();

  on<K extends keyof E>(
    k: K,
    fn: (payload: E[K]) => void
  ): () => void {
    if (!this.handlers.has(k)) {
      this.handlers.set(k, new Set());
    }
    const set = this.handlers.get(k)!;
    set.add(fn as (payload: any) => void);
    return () => {
      set.delete(fn as (payload: any) => void);
    };
  }

  emit<K extends keyof E>(
    k: K,
    ...args: E[K] extends void ? [] : [payload: E[K]]
  ): void {
    const set = this.handlers.get(k);
    if (!set) return;
    const payload = args[0];
    for (const fn of set) {
      fn(payload);
    }
  }
}
