// Brand<T, B> creates a nominal type by intersecting T with a unique symbol property.
// This ensures that two different brands over the same base type are not mutually assignable.
export type Brand<T, B extends string> = T & { readonly __brand: B };

// Define the Email brand
export type Email = Brand<string, 'Email'>;

// Type guard to check if a string is a valid email address.
// Note: This performs a basic regex check. In production, use a more robust validator.
export function isEmail(s: string): s is Email {
  // Basic email regex pattern
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(s);
}

// Casts a string to an Email type, throwing an error if it is not a valid email.
export function asEmail(s: string): Email {
  if (!isEmail(s)) {
    throw new Error(`Invalid email address: ${s}`);
  }
  return s as Email;
}
