type ExtractParams<T extends string> = T extends `${string}:${infer Param}/${infer Rest}`
  ? Param | ExtractParams<Rest>
  : T extends `${string}:${infer Param}`
    ? Param
    : never;

type ParamsForPath<T extends string> = ExtractParams<T> extends never
  ? undefined
  : { [K in ExtractParams<T>]: string };

type RouteFunction<T extends string> = ParamsForPath<T> extends undefined
  ? () => string
  : (params: ParamsForPath<T>) => string;

type RouteMap<T extends Record<string, string>> = {
  [K in keyof T]: RouteFunction<T[K]>;
};

export function defineRoutes<T extends Record<string, string>>(
  routes: T
): RouteMap<T> {
  const result = {} as RouteMap<T>;

  for (const key in routes) {
    const pathTemplate = routes[key];
    const paramNames = extractParamNames(pathTemplate);

    if (paramNames.length === 0) {
      (result as any)[key] = () => pathTemplate;
    } else {
      (result as any)[key] = (params: Record<string, string>) => {
        let resultPath = pathTemplate;
        for (const name of paramNames) {
          const value = params[name];
          if (value === undefined) {
            throw new Error(`Missing param: ${name}`);
          }
          resultPath = resultPath.replace(`:${name}`, value);
        }
        return resultPath;
      };
    }
  }

  return result;
}

function extractParamNames(path: string): string[] {
  const regex = /:([a-zA-Z_][a-zA-Z0-9_]*)/g;
  const names: string[] = [];
  let match: RegExpExecArray | null;
  while ((match = regex.exec(path)) !== null) {
    names.push(match[1]);
  }
  return names;
}
